text:
Componente cliente para Next.js. Observa `#hero` con `IntersectionObserver`, así que no ejecuta lógica en cada evento de scroll.

```tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const links = [
  { href: "#proyecto", label: "Proyecto" },
  { href: "#servicios", label: "Servicios" },
  { href: "#contacto", label: "Contacto" },
];

export function Navbar() {
  const [hasPassedHero, setHasPassedHero] = useState(false);

  useEffect(() => {
    const hero = document.querySelector<HTMLElement>("#hero");

    if (!hero) {
      console.warn('Navbar: no se encontró un elemento con id="hero".');
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        const heroIsAboveViewport =
          !entry.isIntersecting && entry.boundingClientRect.bottom <= 0;

        setHasPassedHero(heroIsAboveViewport);
      },
      { threshold: 0 },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, []);

  return (
    <header
      className={[
        "fixed inset-x-0 top-0 z-50 transition-[background-color,box-shadow,border-color] duration-500 ease-out",
        hasPassedHero
          ? "border-b border-black/6 bg-[#f7f5ef]/90 shadow-[0_12px_40px_-20px_rgba(22,20,16,0.35)] backdrop-blur-xl"
          : "border-b border-transparent bg-transparent shadow-none",
      ].join(" ")}
    >
      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-20 max-w-7xl items-center justify-between px-6 lg:px-10"
      >
        <Link
          href="/"
          aria-label="Ir al inicio"
          className="font-serif text-xl tracking-[-0.04em] text-neutral-950"
        >
          Atelier<span className="text-amber-700">.</span>
        </Link>

        <div className="hidden items-center gap-8 md:flex">
          {links.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="text-sm text-neutral-700 transition-colors hover:text-neutral-950"
            >
              {link.label}
            </Link>
          ))}
        </div>

        <Link
          href="#contacto"
          className="rounded-full bg-neutral-950 px-5 py-2.5 text-sm text-white transition-transform duration-300 hover:-translate-y-0.5"
        >
          Hablemos
        </Link>
      </nav>
    </header>
  );
}
```

El hero debe tener el identificador correspondiente:

```tsx
<section id="hero" className="min-h-screen">
  {/* contenido */}
</section>
```

El cambio de estado sucede exactamente cuando el borde inferior del hero sale por la parte superior del viewport.
